#include "analysis/selection.h"
#include <xrt.h>
#include <stdio.h>
#include <string.h>
#define CHECK(v) do{if(!(v)){fprintf(stderr,"extra:%d %s\n",__LINE__,#v);return 1;}}while(0)
int main(void){
 const char* a="func before() as int\n return 1\nend\nfunc main(...) as int\n return 27\nend\n";
 const char* b="func before() as int\n int more = 2\n return more+1\nend\nfunc main(...) as int\n return 27\nend\n";
 xls_text *old=xlsTextCreate(a,strlen(a),4096,NULL),*updated=xlsTextCreate(b,strlen(b),4096,NULL);xls_session* session=xlsSessionCreate(NULL);xls_analysis_snapshot x={0},y={0},fresh={0};CHECK(old && updated && session && xlsSessionUpdate(session,"e","/memory/e.xl",1,1,old) && xlsSessionSyntax(session,"e",&x));CHECK(xlsSessionUpdate(session,"e","/memory/e.xl",1,2,updated) && xlsSessionSyntax(session,"e",&y));xls_session_stats stats={0};xlsSessionStats(session,&stats);CHECK(stats.fragmentParses>0 && stats.reusedDeclarations>0);
 xls_session* other=xlsSessionCreate(NULL);CHECK(other && xlsSessionUpdate(other,"e","/memory/e.xl",2,1,updated) && xlsSessionSyntax(other,"e",&fresh));size_t at=(size_t)(strstr(b,"27")-b)+1;xls_selection* moved=xlsSelectionCreate(y.syntax,&at,1,NULL,NULL);xls_selection* ref=xlsSelectionCreate(fresh.syntax,&at,1,NULL,NULL);CHECK(moved && ref && xlsSelectionDepth(moved,0)==xlsSelectionDepth(ref,0));for(size_t i=0;i<xlsSelectionDepth(moved,0);++i){xls_selection_range v,w;CHECK(xlsSelectionGet(moved,0,i,&v) && xlsSelectionGet(ref,0,i,&w) && !memcmp(&v,&w,sizeof(v)));}xls_selection_range leaf;CHECK(xlsSelectionGet(moved,0,0,&leaf) && leaf.start==at-1 && leaf.end==at+1);printf("actual fragment parses %llu,reused declarations %llu\n",(unsigned long long)stats.fragmentParses,(unsigned long long)stats.reusedDeclarations);
 xlsSelectionDestroy(ref);xlsSelectionDestroy(moved);xlsSyntaxRelease(fresh.syntax);xlsSyntaxRelease(y.syntax);xlsSyntaxRelease(x.syntax);xlsSessionDestroy(other);xlsSessionDestroy(session);xlsTextRelease(old);xlsTextRelease(updated);
 xstrbuf body;xrtStrBufInit(&body);CHECK(xrtStrBufAppend(&body,(xstrview){"func main(...) as int\n return ",29}));for(size_t i=0;i<700;++i)CHECK(xrtStrBufAppend(&body,(xstrview){i ? "+1" : "1",i ? 2 : 1}));CHECK(xrtStrBufAppend(&body,(xstrview){"\nend\n",5}));xls_text* deep=xlsTextCreate(body.Data,body.Size,8192,NULL);CHECK(deep);session=xlsSessionCreate(NULL);CHECK(session && xlsSessionUpdate(session,"e","/memory/e.xl",1,1,deep) && xlsSessionSyntax(session,"e",&x) && xlsSyntaxAccepted(x.syntax));at=(size_t)(strstr(body.Data,"return ")-body.Data)+7;CHECK(!xlsSelectionCreate(x.syntax,&at,1,NULL,NULL));size_t points[XLS_SELECTION_POSITIONS];for(size_t i=0;i<XLS_SELECTION_POSITIONS;++i)points[i]=at;CHECK(!xlsSelectionCreate(x.syntax,points,XLS_SELECTION_POSITIONS,NULL,NULL));at=body.Size-6;moved=xlsSelectionCreate(x.syntax,&at,1,NULL,NULL);CHECK(moved);xlsSelectionDestroy(moved);xlsSyntaxRelease(x.syntax);xlsSessionDestroy(session);xlsTextRelease(deep);xrtStrBufFree(&body);puts("selection extra passed: actual reused-unit coordinate mapping,depth/candidate bounds and recovery");return 0;
}
